/**
 * L1 Automated Triage — Browser (UX) Canary.
 *
 * A CloudWatch Synthetics Puppeteer canary that complements the API health
 * canary by exercising the real browser experience across the PetSite user
 * journey (home + the four nav pages: adoption list, buy food, Waggle AI,
 * housekeeping). For each page it:
 *
 *   1. Loads the page in a headless browser (following redirects naturally).
 *   2. Watches network responses and uncaught page errors during the visit
 *      (generic, app-agnostic failure signals — catches backend calls that
 *      fail with a 4xx/5xx even if the page itself still returns 200).
 *   3. Asserts that the page's real content rendered (a positive, per-page
 *      selector — e.g. at least one adoption-list item) rather than only
 *      checking that some structural/chrome element (header, body) is
 *      present. This is the primary signal: some app failures are rendered
 *      server-side as a normal 200 page with an error message in place of
 *      the real content, which no HTTP-status or top-level navigation check
 *      can ever detect — only "did the expected content actually appear"
 *      can.
 *   4. As a secondary, non-authoritative signal, flags (and fails on) the
 *      presence of a generic error indicator (Bootstrap's `.alert-danger`
 *      convention). This is corroborating evidence only — the canary does
 *      not depend on any specific error text, since error copy is
 *      application-defined and can change.
 *
 * A failure on any page drives an `l1t-health-` prefixed availability alarm,
 * so UX/page-load/content problems enter the same routing → DevOps Agent
 * triage flow. The specific failing page, URL, and reason are logged so the
 * investigation has concrete evidence to work from.
 *
 * Configuration (environment variables set by the construct):
 *   L1T_UX_URL_PARAMETER_NAME   SSM parameter holding the base site URL
 *   L1T_UX_URL                  inline base site URL (takes precedence)
 *   L1T_UX_KEY_SELECTOR         CSS selector of a key element on the home page (default: body)
 *   L1T_UX_MAX_LOAD_MS          soft page-load budget in ms (logged; default 10000)
 *   L1T_UX_USER_ID              query param appended to journey page URLs (default: user63606)
 *   L1T_UX_ERROR_SELECTOR       secondary generic error-indicator selector (default: .alert-danger)
 */

'use strict';

// The Synthetics runtime provides these modules only inside a canary. Load
// them lazily/tolerantly so the pure decision logic (evaluatePageResult) can
// be unit-tested outside the runtime.
let synthetics;
let log;
try {
    // eslint-disable-next-line global-require
    synthetics = require('Synthetics');
    // eslint-disable-next-line global-require
    log = require('SyntheticsLogger');
} catch (e) {
    synthetics = {
        executeStep: async (_name, fn) => fn(),
        getPage: async () => {
            throw new Error('Synthetics runtime not available (getPage requires the canary runtime)');
        },
        takeScreenshot: async () => {},
    };
    log = { info: () => {}, error: () => {} };
}

/**
 * The PetSite user journey pages to visit, beyond the home page. Each entry
 * defines a positive content selector that must be present for the page to
 * be considered healthy — this is app-specific per page, but the mechanism
 * (assert real content rendered) is the generic, reusable part.
 */
const JOURNEY_PAGES = [
    { name: 'adoption-list', path: '/PetListAdoptions', contentSelector: '.pet-item' },
    { name: 'buy-food', path: '/FoodService', extraQuery: 'petType=puppy', contentSelector: '.card-title' },
    { name: 'waggle-ai', path: '/Waggle', contentSelector: '#chat-messages' },
    { name: 'housekeeping', path: '/housekeeping', contentSelector: '.alert-success, .alert-danger' },
];

async function resolveUrl() {
    const inline = process.env.L1T_UX_URL;
    if (inline && inline.trim().length > 0) {
        return inline.trim();
    }
    const paramName = process.env.L1T_UX_URL_PARAMETER_NAME;
    if (!paramName) {
        throw new Error('No UX target URL configured (set L1T_UX_URL or L1T_UX_URL_PARAMETER_NAME)');
    }
    const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
    const ssm = new SSMClient({});
    const res = await ssm.send(new GetParameterCommand({ Name: paramName, WithDecryption: false }));
    if (!res.Parameter || !res.Parameter.Value) {
        throw new Error(`SSM parameter ${paramName} has no value`);
    }
    return res.Parameter.Value;
}

/**
 * Attach generic, app-agnostic failure listeners to a page: any network
 * response with status >= 400, and any uncaught page-level JS exception.
 * Returns an object the caller can inspect after navigation/settle.
 *
 * @param {import('puppeteer').Page} page
 * @returns {{ failedResponses: Array<{url:string,status:number}>, pageErrors: string[] }}
 */
function attachFailureListeners(page) {
    const failedResponses = [];
    const pageErrors = [];

    const onResponse = (response) => {
        const status = response.status();
        if (status >= 400) {
            failedResponses.push({ url: response.url(), status });
        }
    };
    const onPageError = (err) => {
        pageErrors.push(String(err && err.message ? err.message : err));
    };

    page.on('response', onResponse);
    page.on('pageerror', onPageError);

    return {
        failedResponses,
        pageErrors,
        detach: () => {
            page.off('response', onResponse);
            page.off('pageerror', onPageError);
        },
    };
}

/**
 * Pure decision logic: given the observed signals for a page visit, decide
 * whether the page is healthy and, if not, why. Kept separate from the
 * Puppeteer I/O above so it is directly unit-testable.
 *
 * Evaluation order (first failing check wins, for a clear error message):
 *   1. Expected content missing (primary signal).
 *   2. Generic error indicator present (secondary signal).
 *   3. Any network response >= 400 observed during the visit.
 *   4. Any uncaught page-level JS error observed during the visit.
 *
 * @param {{name:string,url:string,contentSelector:string,errorSelector:string}} page
 * @param {{contentPresent:boolean,dangerPresent:boolean,failedResponses:Array<{url:string,status:number}>,pageErrors:string[]}} signals
 * @returns {{ok:boolean,reason:(string|null)}}
 */
function evaluatePageResult(page, signals) {
    if (!signals.contentPresent) {
        return { ok: false, reason: `Page "${page.name}" (${page.url}) did not render its expected content (${page.contentSelector})` };
    }
    if (signals.dangerPresent) {
        return { ok: false, reason: `Page "${page.name}" (${page.url}) shows a generic error indicator (${page.errorSelector})` };
    }
    if (signals.failedResponses.length > 0) {
        const worst = signals.failedResponses[0];
        return { ok: false, reason: `Page "${page.name}" (${page.url}) had a failed network response: ${worst.status} ${worst.url}` };
    }
    if (signals.pageErrors.length > 0) {
        return { ok: false, reason: `Page "${page.name}" (${page.url}) had an uncaught error: ${signals.pageErrors[0]}` };
    }
    return { ok: true, reason: null };
}

/**
 * Visit a single page, apply the generic network/JS-error checks plus the
 * page's positive content assertion and the secondary generic error-selector
 * check, and throw a descriptive error if the page is unhealthy.
 *
 * @param {import('puppeteer').Page} page
 * @param {string} name step/page name, used for logging and the executeStep label
 * @param {string} url full URL to visit
 * @param {string} contentSelector CSS selector that must be present when the page is healthy
 * @param {string} errorSelector secondary generic error-indicator selector
 * @param {number} maxLoadMs soft page-load budget in ms (logged only)
 */
async function checkPage(page, name, url, contentSelector, errorSelector, maxLoadMs) {
    const listeners = attachFailureListeners(page);
    const startedAt = Date.now();
    try {
        const response = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
        const status = response ? response.status() : null;

        // Let any async fetches/XHRs triggered on load settle briefly so the
        // response listener has a chance to observe them.
        await new Promise((r) => setTimeout(r, 1500));

        const loadMs = Date.now() - startedAt;

        // Primary signal: does the page's real content exist?
        let contentPresent = false;
        try {
            await page.waitForSelector(contentSelector, { timeout: 10000 });
            contentPresent = true;
        } catch (e) {
            contentPresent = false;
        }

        // Secondary, non-authoritative signal: a generic error indicator.
        // For pages whose healthy selector already includes the error
        // selector (e.g. housekeeping's `.alert-success, .alert-danger`),
        // check the danger-specific class separately so it does not always
        // read as "content present" when the page actually failed.
        let dangerPresent = false;
        try {
            dangerPresent = (await page.$(errorSelector)) !== null;
        } catch (e) {
            dangerPresent = false;
        }

        const result = evaluatePageResult(
            { name, url, contentSelector, errorSelector },
            { contentPresent, dangerPresent, failedResponses: listeners.failedResponses, pageErrors: listeners.pageErrors },
        );

        log.info(
            JSON.stringify({
                l1tUxCheck: true,
                page: name,
                url,
                finalUrl: page.url(),
                status,
                loadMs,
                withinBudget: loadMs <= maxLoadMs,
                contentPresent,
                dangerPresent,
                failedResponses: listeners.failedResponses,
                pageErrors: listeners.pageErrors,
                ok: result.ok,
                timestamp: new Date().toISOString(),
            }),
        );

        if (!result.ok) {
            throw new Error(result.reason);
        }
    } finally {
        listeners.detach();
    }
}

const pageLoadBlueprint = async function () {
    const baseUrl = (await resolveUrl()).replace(/\/$/, '');
    const keySelector = process.env.L1T_UX_KEY_SELECTOR || 'body';
    const errorSelector = process.env.L1T_UX_ERROR_SELECTOR || '.alert-danger';
    const maxLoadMs = Number(process.env.L1T_UX_MAX_LOAD_MS) || 10000;
    const userId = process.env.L1T_UX_USER_ID || 'user63606';

    const page = await synthetics.getPage();

    await synthetics.executeStep('home', async function () {
        await checkPage(page, 'home', `${baseUrl}/?userId=${userId}`, keySelector, errorSelector, maxLoadMs);
    });
    await synthetics.takeScreenshot('home', 'loaded');

    for (const journeyPage of JOURNEY_PAGES) {
        const query = [`userId=${userId}`, journeyPage.extraQuery].filter(Boolean).join('&');
        const url = `${baseUrl}${journeyPage.path}?${query}`;
        await synthetics.executeStep(journeyPage.name, async function () {
            await checkPage(page, journeyPage.name, url, journeyPage.contentSelector, errorSelector, maxLoadMs);
        });
        await synthetics.takeScreenshot(journeyPage.name, 'loaded');
    }
};

exports.handler = async () => {
    return await pageLoadBlueprint();
};

// Exported for unit testing (ignored by the Synthetics runtime).
exports.__test__ = {
    evaluatePageResult,
    attachFailureListeners,
    JOURNEY_PAGES,
};
